                    "sql": "CREATE OR REPLACE TABLE maplemonk.zouk_FACEBOOK_CONSOLIDATED_Intermediate AS SELECT Adset_Name, Adset_ID, FB.ad_id, FB.ad_name, \'Facebook_Custom_Facebook_Marketing_Zouk_Meta\' AS Account_Name, Account_ID, Campaign_Name, Campaign_ID, CAST(Fb.date_start AS DATE) AS Date, SUM(CLICKS) AS Clicks, SUM(IFNULL(inline_link_clicks,0)) AS Link_Clicks, SUM(SPEND) AS Spend, SUM(IMPRESSIONS) AS Impressions, SUM(IFNULL(Fc.Conversions,0)) AS Conversions, SUM(IFNULL(reach,0)) AS reach, SUM(IFNULL(frequency,0)) AS frequency, SUM(IFNULL(Fcv.Conversion_Value,0)) AS Conversion_Value, SUM(IFNULL(fd.add_to_carts,0)) AS Add_to_carts, SUM(IFNULL(fdv.add_to_cart_value,0)) AS Add_to_cart_value, SUM(IFNULL(Fp.purchase, 0)) AS Purchase, SUM(IFNULL(Fv.video_views, 0)) AS Video_Views, SUM(IFNULL(Fcm.Comment, 0)) AS Comment, SUM(IFNULL(Frc.post_reaction,0)) AS Post_Reaction, SUM(IFNULL(Feg.page_engagement,0)) AS Page_Engagement, SUM(IFNULL(Fl.Facebook_Like, 0)) AS Facebook_Like, SUM(IFNULL(fe.landing_page_views,0)) AS Landing_page_views, SUM(IFNULL(ff.initiate_checkouts,0)) AS Initiate_checkouts, SUM(IFNULL(ffv.initiate_checkouts_value,0)) AS Initiate_checkouts_value, \'Facebook\' AS Channel, \'Facebook_Custom_Facebook_Marketing_Zouk_Meta\' AS Account FROM ( SELECT * FROM maplemonk.Custom_Facebook_Marketing_Zouk_Meta_CustomCampaigns_data WHERE NOT(IFNULL(CONCAT(CAST(date_start AS DATE), ad_id), \'\') IN ( SELECT DISTINCT CONCAT(CAST(date_start AS DATE), ad_id) FROM `MapleMonk.zouk_db_product_customcampaigns_data` WHERE LOWER(IFNULL(ad_name, \'\')) LIKE \'%catalogue%\' )) ) FB left join ( select ad_id ,ad_name ,date_start ,SUM(ifnull(cast(JSON_EXTRACT_SCALAR(C,\'$.7d_click\') as FLOAT64),0) + ifnull(cast(JSON_EXTRACT_SCALAR(C,\'$.1d_view\') as FLOAT64),0)) Conversions from maplemonk.Custom_Facebook_Marketing_Zouk_Meta_CustomCampaigns_data left join UNNEST(ACTIONS) C where JSON_EXTRACT_SCALAR(C,\'$.action_type\')=\'offsite_conversion.fb_pixel_purchase\' group by ad_id ,ad_name ,date_start )Fc ON Fb.ad_id = Fc.ad_id and Fb.date_start=Fc.date_start LEFT JOIN ( SELECT ad_id ,ad_name ,date_start ,SUM(IFNULL(CAST(JSON_EXTRACT_SCALAR(C,\'$.value\') AS FLOAT64),0)) purchase FROM maplemonk.Custom_Facebook_Marketing_Zouk_Meta_CustomCampaigns_data left join UNNEST(ACTIONS) C WHERE JSON_EXTRACT_SCALAR(C,\'$.action_type\') = \'purchase\' GROUP BY ad_id ,ad_name ,date_start ) Fp ON Fb.ad_id = Fp.ad_id AND Fb.date_start = Fp.date_start LEFT JOIN ( SELECT ad_id ,ad_name ,date_start ,SUM(CAST(JSON_EXTRACT_SCALAR(C,\'$.value\') AS FLOAT64)) AS Facebook_Like FROM `MapleMonk.Custom_Facebook_Marketing_Zouk_Meta_customcampaigns_data` left join UNNEST(ACTIONS) C WHERE JSON_EXTRACT_SCALAR(C,\'$.action_type\') = \'like\' GROUP BY ad_id, ad_name, date_start ) Fl ON Fb.ad_id = Fl.ad_id AND Fb.date_start = Fl.date_start LEFT JOIN ( SELECT ad_id ,ad_name ,date_start ,SUM(CAST(JSON_EXTRACT_SCALAR(C,\'$.value\') AS FLOAT64)) AS comment FROM `MapleMonk.Custom_Facebook_Marketing_Zouk_Meta_customcampaigns_data` left join UNNEST (ACTIONS) C WHERE JSON_EXTRACT_SCALAR(C,\'$.action_type\') = \'comment\' GROUP BY ad_id, ad_name, date_start ) Fcm ON Fb.ad_id = Fcm.ad_id AND Fb.date_start = Fcm.date_start LEFT JOIN ( SELECT ad_ID ,ad_name ,date_start ,SUM(CAST(JSON_EXTRACT_SCALAR(C,\'$.value\')AS FLOAT64)) Page_Engagement FROM `MapleMonk.Custom_Facebook_Marketing_Zouk_Meta_customcampaigns_data` left join UNNEST (ACTIONS) C WHERE JSON_EXTRACT_SCALAR(C,\'$.action_type\') = \'page_engagement\' GROUP BY ad_id ,ad_name ,date_start ) Feg ON Fb.ad_id = Feg.ad_id AND Fb.date_start = Feg.date_start LEFT JOIN ( SELECT ad_ID ,ad_name ,date_start ,SUM(CAST(JSON_EXTRACT_SCALAR(C,\'$.value\') AS FLOAT64)) Post_Reaction FROM `MapleMonk.Custom_Facebook_Marketing_Zouk_Meta_customcampaigns_data` left join UNNEST (ACTIONS) C WHERE JSON_EXTRACT_SCALAR(C,\'$.action_type\') = \'post_reaction\' GROUP BY ad_id ,ad_name ,date_start ) Frc ON Fb.ad_id = Frc.ad_id AND Fb.date_start = Frc.date_start LEFT JOIN ( SELECT ad_id ,Ad_name ,date_start ,SUM(CAST(JSON_EXTRACT_SCALAR(C,\'$.value\') AS FLOAT64)) video_views FROM maplemonk.Custom_Facebook_Marketing_Zouk_Meta_CustomCampaigns_data left join UNNEST(ACTIONS) C WHERE JSON_EXTRACT_SCALAR(C,\'$.action_type\') = \'video_view\' GROUP BY ad_id ,Ad_name ,date_start ) Fv ON Fb.ad_id = Fv.ad_id AND Fb.date_start = Fv.date_start left join ( select ad_id ,ad_name ,date_start ,SUM(ifnull(cast(JSON_EXTRACT_SCALAR(CV,\'$.7d_click\') as FLOAT64),0) + ifnull(cast(JSON_EXTRACT_SCALAR(CV,\'$.1d_view\') as FLOAT64),0)) Conversion_Value from maplemonk.Custom_Facebook_Marketing_Zouk_Meta_CustomCampaigns_data left join UNNEST(ACTION_VALUES) CV where JSON_EXTRACT_SCALAR(Cv,\'$.action_type\')=\'offsite_conversion.fb_pixel_purchase\' group by ad_id ,ad_name ,date_start )Fcv ON Fb.ad_id = Fcv.ad_id and Fb.date_start=Fcv.date_start left join ( select ad_id ,date_start ,SUM(cast(JSON_EXTRACT_SCALAR(C,\'$.value\') as FLOAT64)) add_to_carts from maplemonk.Custom_Facebook_Marketing_Zouk_Meta_CustomCampaigns_data left join UNNEST(ACTIONS) C where JSON_EXTRACT_SCALAR(C,\'$.action_type\')=\'offsite_conversion.fb_pixel_add_to_cart\' group by ad_id,date_start having SUM(cast(JSON_EXTRACT_SCALAR(C,\'$.value\') as FLOAT64)) is not null )Fd ON Fb.ad_id = Fd.ad_id and Fb.date_start=Fd.date_start left join ( select ad_id ,date_start ,SUM(cast(JSON_EXTRACT_SCALAR(CV,\'$.value\') as FLOAT64)) Add_to_cart_Value from maplemonk.Custom_Facebook_Marketing_Zouk_Meta_CustomCampaigns_data left join UNNEST(ACTION_VALUES) CV where JSON_EXTRACT_SCALAR(Cv,\'$.action_type\')=\'offsite_conversion.fb_pixel_add_to_cart\' group by ad_id,date_start having SUM(cast(JSON_EXTRACT_SCALAR(CV,\'$.value\') as FLOAT64)) is not null )Fdv ON Fb.ad_id = Fdv.ad_id and Fb.date_start=Fdv.date_start left join ( select ad_id ,date_start ,SUM(cast(JSON_EXTRACT_SCALAR(C,\'$.value\') as FLOAT64)) Landing_page_views from maplemonk.Custom_Facebook_Marketing_Zouk_Meta_CustomCampaigns_data l