'\') and collection is not null and collection != \'\' ) qualify row_number() over(partition by lower(ifnull(ad_id,\'\')), lower(ifnull(AD_NAME,\'\')) order by 1) = 1 )fsm on lower(fsm.ad_id) = lower(mc.ad_id) and lower(fsm.AD_NAME) = lower(mc.AD_NAME) ) select * from facebook where category is not null union all select * from facebook_category where category is not null union all select * from facebook_collection ; CREATE OR REPLACE TABLE maplemonk.zouk_DB_Product_FACEBOOK_CONSOLIDATED AS select Adset_Name ,Adset_ID ,FB.ad_id ,FB.ad_name ,\'Facebook_Custom_Facebook_Marketing_Zouk_Meta\' as Account_Name ,FB.Account_ID ,Campaign_Name ,Campaign_ID ,cast(Fb.date_start as date) Date ,SUM(CLICKS) Clicks ,sum(ifnull(inline_link_clicks,0)) Link_Clicks ,SUM(SPEND) Spend ,SUM(IMPRESSIONS) Impressions ,SUM(ifnull(Fc.Conversions,0)) Conversions ,sum(ifnull(reach,0)) reach ,sum(ifnull(frequency,0)) as frequency ,SUM(ifnull(Fcv.Conversion_Value,0)) Conversion_Value ,sum(ifnull(fd.add_to_carts,0)) Add_to_carts ,sum(ifnull(fdv.add_to_cart_value,0)) Add_to_cart_value ,sum(ifnull(fp.purchase,0)) Purchase ,sum(ifnull(fv.video_views,0)) video_views ,SUM(IFNULL(Fcm.Comment, 0)) AS Comment ,SUM(IFNULL(Frc.post_reaction,0)) AS Post_Reaction ,SUM(IFNULL(Feg.page_engagement,0)) AS Page_Engagement ,SUM(IFNULL(Fl.Facebook_Like, 0)) AS Facebook_Like ,sum(ifnull(fe.landing_page_views,0)) Landing_page_views ,sum(ifnull(ff.initiate_checkouts,0)) Initiate_checkouts ,sum(ifnull(ffv.initiate_checkouts_value,0)) Initiate_checkouts_value ,\'Facebook\' Channel ,\'Facebook_Custom_Facebook_Marketing_Zouk_Meta\' Account ,fm.category ,fm.collection from( select * from `MapleMonk.zouk_db_product_customcampaigns_data` where lower(ifnull(ad_name,\'\')) like \'%catalogue%\' ) FB left join ( select ad_id ,ad_name ,date_start ,SUM(ifnull(cast(JSON_EXTRACT_SCALAR(C,\'$.7d_click\') as FLOAT64),0) + ifnull(cast(JSON_EXTRACT_SCALAR(C,\'$.1d_view\') as FLOAT64),0)) Conversions from maplemonk.zouk_db_product_customcampaigns_data left join UNNEST(ACTIONS) C where JSON_EXTRACT_SCALAR(C,\'$.action_type\')=\'offsite_conversion.fb_pixel_purchase\' group by ad_id ,ad_name ,date_start )Fc ON Fb.ad_id = Fc.ad_id and Fb.date_start=Fc.date_start left join ( select ad_id ,ad_name ,date_start ,SUM(ifnull(cast(JSON_EXTRACT_SCALAR(CV,\'$.7d_click\') as FLOAT64),0) + ifnull(cast(JSON_EXTRACT_SCALAR(CV,\'$.1d_view\') as FLOAT64),0)) Conversion_Value from maplemonk.zouk_db_product_customcampaigns_data left join UNNEST(ACTION_VALUES) CV where JSON_EXTRACT_SCALAR(Cv,\'$.action_type\')=\'offsite_conversion.fb_pixel_purchase\' group by ad_id ,ad_name ,date_start )Fcv ON Fb.ad_id = Fcv.ad_id and Fb.date_start=Fcv.date_start LEFT JOIN ( SELECT ad_id ,date_start ,SUM(IFNULL(CAST(JSON_EXTRACT_SCALAR(C,\'$.value\') AS FLOAT64),0)) purchase FROM `MapleMonk.zouk_db_product_customcampaigns_data` LEFT JOIN UNNEST(ACTIONS) C WHERE JSON_EXTRACT_SCALAR(C,\'$.action_type\')=\'purchase\' GROUP BY 1,2 ) Fp ON FB.ad_id = Fp.ad_id AND FB.date_start = Fp.date_start LEFT JOIN ( SELECT ad_id ,date_start ,SUM(CAST(JSON_EXTRACT_SCALAR(C,\'$.value\') AS FLOAT64)) video_views FROM `MapleMonk.zouk_db_product_customcampaigns_data` LEFT JOIN UNNEST(ACTIONS) C WHERE JSON_EXTRACT_SCALAR(C,\'$.action_type\') = \'video_view\' GROUP BY 1,2 ) Fv ON FB.ad_id = Fv.ad_id AND FB.date_start = Fv.date_start LEFT JOIN ( SELECT ad_id ,date_start ,SUM(CAST(JSON_EXTRACT_SCALAR(C,\'$.value\') AS FLOAT64)) Comment FROM `MapleMonk.zouk_db_product_customcampaigns_data` LEFT JOIN UNNEST(ACTIONS) C WHERE JSON_EXTRACT_SCALAR(C,\'$.action_type\') = \'comment\' GROUP BY 1,2 ) Fcm ON FB.ad_id = Fcm.ad_id AND FB.date_start = Fcm.date_start LEFT JOIN ( SELECT ad_id ,date_start ,SUM(CAST(JSON_EXTRACT_SCALAR(C,\'$.value\') AS FLOAT64)) Facebook_Like FROM `MapleMonk.zouk_db_product_customcampaigns_data` LEFT JOIN UNNEST(ACTIONS) C WHERE JSON_EXTRACT_SCALAR(C,\'$.action_type\') = \'like\' GROUP BY 1,2 ) Fl ON FB.ad_id = Fl.ad_id AND FB.date_start = Fl.date_start LEFT JOIN ( SELECT ad_id ,date_start ,SUM(CAST(JSON_EXTRACT_SCALAR(C,\'$.value\') AS FLOAT64)) Page_Engagement FROM `MapleMonk.zouk_db_product_customcampaigns_data` LEFT JOIN UNNEST(ACTIONS) C WHERE JSON_EXTRACT_SCALAR(C,\'$.action_type\') = \'page_engagement\' GROUP BY 1,2 ) Feg ON FB.ad_id = Feg.ad_id AND FB.date_start = Feg.date_start LEFT JOIN ( SELECT ad_id ,date_start ,SUM(CAST(JSON_EXTRACT_SCALAR(C,\'$.value\') AS FLOAT64)) Post_Reaction FROM `MapleMonk.zouk_db_product_customcampaigns_data` LEFT JOIN UNNEST(ACTIONS) C WHERE JSON_EXTRACT_SCALAR(C,\'$.action_type\') = \'post_reaction\' GROUP BY 1,2 ) Frc ON FB.ad_id = Frc.ad_id AND FB.date_start = Frc.date_start left join ( select ad_id ,date_start ,SUM(cast(JSON_EXTRACT_SCALAR(C,\'$.value\') as FLOAT64)) add_to_carts from maplemonk.zouk_db_product_customcampaigns_data left join UNNEST(ACTIONS) C where JSON_EXTRACT_SCALAR(C,\'$.action_type\')=\'offsite_conversion.fb_pixel_add_to_cart\' group by ad_id,date_start having SUM(cast(JSON_EXTRACT_SCALAR(C,\'$.value\') as FLOAT64)) is not null )Fd ON Fb.ad_id = Fd.ad_id and Fb.date_start=Fd.date_start left join ( select ad_id ,date_start ,SUM(cast(JSON_EXTRACT_SCALAR(CV,\'$.value\') as FLOAT64)) Add_to_cart_Value from maplemonk.zouk_db_product_customcampaigns_data left join UNNEST(ACTION_VALUES) CV where JSON_EXTRACT_SCALAR(Cv,\'$.action_type\')=\'offsite_conversion.fb_pixel_add_to_cart\' group by ad_id,date_start having SUM(cast(JSON_EXTRACT_SCALAR(CV,\'$.value\') as FLOAT64)) is not null )Fdv ON Fb.ad_id = Fdv.ad_id and Fb.date_start=Fdv.date_start left join ( select ad_id ,date_start ,SUM(cast(JSON_EXTRACT_SCALAR(C,\'$.value\') as FLOAT64)) Landing_page_views from maplemonk.zouk_db_product_customcampaigns_data left join UNNEST(ACTIONS) C where JSON_EXTRACT_SCALAR(C,\'$.action_type\')=\'landing_page_view\' group by ad_id,date_start having SUM(cast(JSON_EXTRACT_SCALAR(C,\'$.value\') as FLOAT64)) is not null )Fe ON Fb.ad_id = Fe.ad_id and Fb.date_start=Fe.date_start left join ( select ad_id ,date_start ,SUM(cast(JSON_EXTRACT_SCALAR(C,\'$.value\') as FLOAT64)) Initiate_checkouts from maplemonk.zouk_db_product_customcampaigns_data left join UNNEST(ACTIONS) C where JSON_EXTRACT_SCALAR(C,\'$.action_type\')=\'offsite_conversion.fb_pixel_initiate_checkout\' group by ad_id,date_start having SUM(cast(JSON_EXTRACT_SCALAR(C,\'$.value\') as FLOAT64)) is not null )Ff ON Fb.ad_id = Ff.ad_id and Fb.date_start=Ff.date_start left join ( select ad_id ,date_start ,SUM(cast(JSON_EXTRACT_SCALAR(CV,\'$.value\') as FLOAT64)) Initiate_checkouts_Value from maplemonk.zouk_db_product_customcampaigns_data left join UNNEST(ACTION_VALUES) CV where JSON_EXTRACT_SCALAR(Cv,\'$.action_type\')=\'offsite_conversion.fb_pixel_initiate_checkout\' group by ad_id,date_start having SUM(cast(JSON_EXTRACT_SCALAR(CV,\'$.value\') as FLOAT64)) is not null )Ffv ON Fb.ad_id = Ffv.ad_id and Fb.date_start=Ffv.date_start left join ( select * from MapleMonk.FINAL_SKU_MASTER qualify row_number() over(partition by lower(Channel_Product_Id) order by 1) = 1 )Fm on lower(trim(SPLIT(FB.product_id, \',\')[OFFSET(0)])) = LOWER(TRIM(SPLIT(Fm.Channel_Product_Id, \'-\')[OFFSET(ARRAY_LENGTH(SPLIT(Fm.Channel_Product_Id, \'-\')) - 1)])) group by Adset_Name, Adset_ID,fb.ad_id,fb.AD_NAME, Account_Name, Account_ID, Campaign_Name, Campaign_ID,Fb.date_start,fm.category,fm.collection ; CREATE OR REPLACE TABLE maplemonk.zouk_FACEBOOK_CONSOLIDATED as ( select Adset_Name, Adset_ID, ad_id, ad_name, Account_Name, Account_ID, Campaign_Name, Campaign_ID, Date, Channel, Account, CATEGORY, COLLECTION, reach, frequency, Clicks, Link_Clicks, Spend, Impressions, Conversions, Conversion_Value,purchase, video_views,Comment, Post_Reaction,Page_Engagement,Facebook_Like,Add_to_carts, Add_to_cart_value, Landing_page_views, Initiate_checkouts, Initiate_checkouts_value from maplemonk.zouk_FACEBOOK_CONSOLIDATED_overall ) union all ( select Adset_Name, Adset_ID, ad_id, ad_name, Account_Name, Account_ID, Campaign_Name, Campaign_ID, Date, Channel, Account, CATEGORY, COLLECTION, reach, frequency, Clicks, Link_Clicks, Spend, Impressions, Conversions, Conversion_Value,purchase, video_views, Comment, Post_Reaction,Page_Engagement,Facebook_Like,Add_to_carts, Add_to_cart_value,Landing_page_views, Initiate_checkouts, Initiate_checkouts_value from maplemonk.zouk_DB_Product_FACEBOOK_CONSOLIDATED ) ;",
                    "transaction": true
